import java.util.concurrent.*

class Bad1 {
    fun getOrders(services: List<Any>): List<Any> {
        val futures = services.map { CompletableFuture.supplyAsync { it } }
        return futures
            .filter { it.isDone && !it.isCompletedExceptionally }
            .map { it.join() } // bad, NO timeout provided
    }
}

class Bad2 {
    fun getOrders(futures: List<CompletableFuture<Any>>): List<Any> {
        val allResult = CompletableFuture.allOf(*futures.toTypedArray())
        try {
            allResult.get() // missing timeout
        } catch (e: Exception) { }
        return futures
            .filter { it.isDone && !it.isCompletedExceptionally }
            .map { it.join() } // bad since has NO timeout above
    }
}

import java.util.concurrent.*

class Good1 {
    fun getOrders(futures: List<CompletableFuture<Any>>): List<Any> {
        val allResult = CompletableFuture.allOf(*futures.toTypedArray())
        try {
            allResult.get(5L, TimeUnit.SECONDS) // good
        } catch (e: Exception) { }
        return futures
            .filter { it.isDone && !it.isCompletedExceptionally }
            .map { it.join() } // good, timeout provided above
    }
}

class Good2 {
    fun doSomething(futures: Array<CompletableFuture<Any>>) {
        CompletableFuture.allOf(*futures)
            .orTimeout(5L, TimeUnit.SECONDS)
            .join() // good - chained orTimeout
    }
}

import java.util.concurrent.*

class Foo {
    fun extract(str: String, items: List<String>): String {
        return String.join(", ", items) // not Future.join, no violation
    }
}

import java.util.concurrent.*

class Bar {
    fun foo(futures: Array<CompletableFuture<Any>>) {
        CompletableFuture.allOf(*futures).join() // bad
    }
}

import java.util.concurrent.*

class Good3 {
    fun doSomething(futures: Array<CompletableFuture<Any>>) {
        CompletableFuture.allOf(*futures)
            .completeOnTimeout(null, 5L, TimeUnit.SECONDS)
            .join() // good - completeOnTimeout used
    }
}
